	/** 
	 * jumpstart the process by instantiating2 Measure
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		measureId = MeasureService.getMeasureInstance()
		.createMeasure( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		MeasureService.getMeasureInstance()
				.createMeasure( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.measureSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Measure : " + successValue.getMeasureId());
							  if (successValue.getMeasureId().equals(measureId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfMeasureList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Measure test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on measure consumed")
					);
			subscriber.measureSubscribe( measureId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Measure : " + successValue.getMeasureId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfMeasureList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on measure for measureId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Measure. 
	 */
	protected Measure read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Measure" );

		Measure entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Measure with primary key" );
		msg.append( measureId );
		
		MeasureFetchOneSummary fetchOneSummary = new MeasureFetchOneSummary( measureId );

		try {
			entity = MeasureService.getMeasureInstance().getMeasure( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Measure " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Measure.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Measure." );

		StringBuilder msg = new StringBuilder( "Failed to update a Measure : " );        
		Measure entity = read();
		UpdateMeasureCommand command = generateUpdateCommand();
		command.setMeasureId(entity.getMeasureId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Measure." );

			// for use later on...
			measureId = entity.getMeasureId();

			MeasureService proxy = MeasureService.getMeasureInstance();  

			proxy.updateMeasure( command ).get();

			LOGGER.info( "-- Successfully saved Measure - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + measureId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Measure.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Measure." );

		Measure entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Measure with id " + measureId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Measure with id " + measureId );

			throw e;
		}

		try{
			MeasureService.getMeasureInstance().delete( new DeleteMeasureCommand( entity.getMeasureId() ) ).get();
			LOGGER.info( "-- Successfully deleted Measure with id " + measureId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Measure with id " + measureId );

			throw e;
		}
	}

	/**
	 * get all Measures.
	 */
	protected List<Measure> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Measures:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Measure : " );        
		List<Measure> collection  = new ArrayList<>();

		try {
			// call the static get method on the MeasureService
			collection = MeasureService.getMeasureInstance().getAllMeasure();
			assertNotNull( collection, "An Empty collection of Measure was incorrectly returned.");
			
			// Now print out the values
			Measure entity = null;            
			Iterator<Measure> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getMeasureId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

